const trimOpenConnectRequests = `-- name: TrimOpenConnectRequests :execrows
DELETE FROM provider_connect_requests
WHERE id_digest IN (
    SELECT r.id_digest FROM provider_connect_requests r
    WHERE r.user_id = $1 AND r.used_at IS NULL AND r.expires_at > now()
    ORDER BY r.created_at DESC, r.id_digest
    OFFSET $2::int
)
`

type TrimOpenConnectRequestsParams struct {
	UserID uuid.UUID
	Keep   int32
}

// Keeps a person's newest keep open requests; older open ones are dropped.
func (q *Queries) TrimOpenConnectRequests(ctx context.Context, arg TrimOpenConnectRequestsParams) (int64, error) {
	result, err := q.db.Exec(ctx, trimOpenConnectRequests, arg.UserID, arg.Keep)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

